 holdpath=ROOT/'research/ir-source-access-holds-2026-10-15/holds-v8.json';holdhosts={v['exact_host'] for v in json.loads(holdpath.read_bytes())['holds']};inputs[str(holdpath.relative_to(ROOT))]=sha(holdpath)
 from urllib.parse import urlsplit
